using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Service setup ---
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools ---
var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearchSimulator.Search(query);
        },
        "web_search",
        "Searches the web for information on a given query. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("The note text to save")] string note) =>
        {
            notepad.Add(note);
            Console.WriteLine($"  📝 Note saved ({notepad.Count} total)");
            return $"Note saved. You now have {notepad.Count} note(s).";
        },
        "save_note",
        "Saves a research note for later reference when writing the summary."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notepad.GetAll();
            Console.WriteLine($"  📋 Reading {notes.Count} note(s)");
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n---\n", notes);
        },
        "read_notes",
        "Reads all previously saved research notes."),
};

// --- Agent ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = tools,
            ToolMode = ChatToolMode.Auto,
        },
    },
    loggerFactory);

// --- Run ---
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔬 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(
    $"""
    Research the following topic thoroughly:

    "{topic}"

    Instructions:
    1. Search the web for information using multiple varied queries.
    2. Save important findings as notes using the save_note tool.
    3. After gathering enough information, read your notes with read_notes.
    4. Write a comprehensive summary of your findings.

    Be thorough but concise. Cite key facts you discover.
    """,
    session);

Console.WriteLine("\n═══════════════════════════════════════");
Console.WriteLine("📄 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

// --- Helpers ---

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? "The impact of large language models on software engineering"
        : topic;
}

// --- Notepad tool backing store ---
sealed class Notepad
{
    private readonly List<string> _notes = [];
    public int Count => _notes.Count;
    public void Add(string note) => _notes.Add(note);
    public List<string> GetAll() => [.. _notes];
}

// --- Simulated web search (replace with a real search API for production) ---
static class WebSearchSimulator
{
    private static readonly Dictionary<string, string[]> s_knowledgeBase = new(StringComparer.OrdinalIgnoreCase)
    {
        ["large language models"] =
        [
            "Large language models (LLMs) are neural networks trained on massive text datasets. GPT-4, Claude, and Gemini are leading examples as of 2025.",
            "LLMs use transformer architecture with billions of parameters to generate human-like text, answer questions, and perform reasoning tasks.",
            "Key concerns include hallucination (generating plausible but false information), high computational costs, and potential biases in training data.",
        ],
        ["software engineering AI"] =
        [
            "AI-powered coding assistants like GitHub Copilot have shown 30-55% productivity gains in controlled studies.",
            "Common AI applications in software engineering include code generation, bug detection, test generation, code review, and documentation.",
            "Challenges include over-reliance on AI suggestions, security vulnerabilities in generated code, and the need for developers to verify AI output.",
        ],
        ["climate change"] =
        [
            "Global average temperatures have risen approximately 1.1°C above pre-industrial levels as of 2024.",
            "The Paris Agreement aims to limit warming to 1.5°C, but current policies project 2.5-2.9°C by 2100.",
            "Renewable energy capacity has grown rapidly, with solar and wind now cheaper than fossil fuels in most regions.",
        ],
        ["quantum computing"] =
        [
            "Quantum computers use qubits that can exist in superposition, enabling parallel computation for certain problem types.",
            "Google, IBM, and other companies have demonstrated quantum advantage on specific tasks, though general-purpose quantum computing remains years away.",
            "Key applications include cryptography, drug discovery, optimization problems, and materials science simulation.",
        ],
    };

    public static string Search(string query)
    {
        var results = new List<string>();

        foreach (var (key, snippets) in s_knowledgeBase)
        {
            if (query.Contains(key, StringComparison.OrdinalIgnoreCase)
                || key.Contains(query, StringComparison.OrdinalIgnoreCase)
                || query.Split(' ').Any(w => w.Length > 3 && key.Contains(w, StringComparison.OrdinalIgnoreCase)))
            {
                results.AddRange(snippets);
            }
        }

        if (results.Count == 0)
        {
            results.Add($"Search results for \"{query}\": General information about this topic is available from various academic and industry sources. Specific details would require a specialized search API.");
        }

        return string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r}"));
    }
}

